import type {User} from'firebase/auth';import{onAuthStateChanged,signOut}from'firebase/auth';import{auth}from'./firebase';import{importRecipesInBatches,loadCloud,recipeFingerprint,saveCloudState,syncChangedRecipes}from'./cloudSync';import AuthModal from'./AuthModal';import CopyMeThatImporter from'./CopyMeThatImporter';import type{CopyMeThatRecipe}from'./importers/copyMeThat';import{deleteLocalPhoto,hydrateLocalPhotos,saveLocalPhoto}from'./photoStore';import{uploadRecipePhoto}from'./cloudinary';
