{id:'r1',title:'Creamy Poblano Chicken',image:'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?auto=format&fit=crop&w=1200&q=80',servings:4,favorite:true,time:45,allergens:['Dairy'],tags:['Weeknight','Mexican-inspired'],ingredients:['2 lb boneless skinless chicken breasts','4 poblano peppers','1 tbsp olive oil','1 small yellow onion, diced','3 garlic cloves, minced','1 tsp ground cumin','1 cup chicken broth','1 cup heavy cream','8 oz Oaxaca cheese, shredded','1 tsp kosher salt','1/2 tsp black pepper','2 tbsp chopped cilantro'],instructions:['Roast the poblano peppers under the broiler, turning occasionally, until blistered on all sides.','Place peppers in a covered bowl for 10 minutes, then peel, seed, and slice.','Season chicken with salt, pepper, and cumin. Heat olive oil in a large skillet over medium-high heat.','Sear chicken for 5 to 6 minutes per side, until cooked through. Transfer to a plate.','Cook onion in the same skillet for 4 minutes. Add garlic and cook for 30 seconds.','Add chicken broth and scrape up the browned bits. Stir in cream and sliced poblanos.','Return chicken to the skillet, top with cheese, and simmer for 5 minutes.','Garnish with cilantro and serve.']},
{id:'r2',title:'Sunday Skillet Lasagna',image:'https://images.unsplash.com/photo-1574894709920-11b28e7367e3?auto=format&fit=crop&w=1200&q=80',servings:6,favorite:false,time:50,allergens:['Dairy','Gluten'],tags:['Comfort food','One pan'],ingredients:['1 tbsp olive oil','1 lb lean ground beef','1 small onion, diced','3 garlic cloves, minced','24 oz marinara sauce','14.5 oz crushed tomatoes','8 oz lasagna noodles, broken','1 1/2 cups water','1 tsp Italian seasoning','1 cup ricotta cheese','1 1/2 cups shredded mozzarella','1/4 cup grated Parmesan'],instructions:['Heat olive oil in a deep oven-safe skillet over medium-high heat.','Brown the beef with the onion for 6 to 8 minutes. Drain excess fat.','Add garlic and Italian seasoning; cook for 30 seconds.','Stir in marinara, tomatoes, water, and noodles.','Cover and simmer 18 to 22 minutes, stirring occasionally.','Dollop ricotta over the skillet and sprinkle with mozzarella and Parmesan.','Broil for 2 to 3 minutes until browned. Rest 5 minutes and serve.']},
{id:'r3',title:'Lemon Herb Salmon Bowls',image:'https://images.unsplash.com/photo-1467003909585-2f8a72700288?auto=format&fit=crop&w=1200&q=80',servings:4,favorite:false,time:35,allergens:['Fish'],tags:['Fresh','High protein'],ingredients:['4 salmon fillets','2 cups cooked quinoa','1 cucumber, diced','1 pint cherry tomatoes, halved','2 avocados, sliced','2 tbsp olive oil','1 lemon, zested and juiced','2 tbsp chopped dill','1/2 tsp garlic powder','Salt and pepper'],instructions:['Heat oven to 425°F and line a sheet pan.','Season salmon with olive oil, lemon zest, garlic powder, salt, and pepper.','Roast salmon 10 to 13 minutes until it flakes easily.','Divide quinoa among bowls.','Add cucumber, tomatoes, avocado, and salmon.','Finish with lemon juice and dill.']},
{id:'r4',title:'Peanut Sesame Noodles',image:'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=1200&q=80',servings:4,favorite:false,time:20,allergens:['Peanuts','Soy','Gluten'],tags:['Quick','Vegetarian'],ingredients:['12 oz noodles','1/2 cup creamy peanut butter','3 tbsp soy sauce','2 tbsp rice vinegar','1 tbsp sesame oil','1 tbsp honey','1 tsp grated ginger','1 garlic clove, grated','1/3 cup warm water','1 cucumber, sliced','2 green onions, sliced'],instructions:['Cook noodles according to package directions.','Whisk peanut butter, soy sauce, vinegar, sesame oil, honey, ginger, and garlic.','Whisk in warm water until smooth.','Toss noodles with sauce.','Top with cucumber and green onions.']}
